require_once __DIR__.'/config/app.php';require_login();$orderId=(int)($_GET['order_id']??0);$sql='SELECT o.user_id,p.proof_image FROM orders o JOIN payments p ON p.order_id=o.id WHERE o.id=?';$stmt=db()->prepare($sql);$stmt->execute([$orderId]);$row=$stmt->fetch();if(!$row||(!$row['proof_image'])||(!is_admin()&&(int)$row['user_id']!==(int)current_user()['id'])){http_response_code(404);exit('Bukti pembayaran tidak ditemukan.');}$path=APP_ROOT.'/'.ltrim($row['proof_image'],'/');$real=realpath($path);$base=realpath(APP_ROOT.'/storage/payment-proofs');if(!$real||!$base||!str_starts_with($real,$base.DIRECTORY_SEPARATOR)){http_response_code(404);exit('File tidak ditemukan.');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($real);if(!in_array($mime,['image/jpeg','image/png','image/webp'],true)){http_response_code(403);exit('File tidak valid.');}header('Content-Type: '.$mime);header('Content-Length: '.filesize($real));header('Content-Disposition: inline; filename="bukti-pembayaran.'.pathinfo($real,PATHINFO_EXTENSION).'"');readfile($real);exit;
